import random
from typing import Iterable, TypeVar

T = TypeVar("T")


def reservoir_sample(stream: Iterable[T], k: int) -> list[T]:
    """Sample k items from a stream using reservoir sampling (Vitter's R algorithm).

    Works when the stream length is unknown or too large to fit in memory.
    Each subset of size k is equally likely.
    """
    if k < 0:
        raise ValueError("k must be non-negative")

    reservoir: list[T] = []
    for i, item in enumerate(stream):
        if i < k:
            reservoir.append(item)
        else:
            j = random.randint(0, i)
            if j < k:
                reservoir[j] = item
    return reservoir


# ── Tests ──────────────────────────────────────────────────────────────────────

def test_returns_empty_for_zero_k():
    assert reservoir_sample(range(100), 0) == []


def test_returns_empty_for_empty_stream():
    assert reservoir_sample([], 5) == []


def test_returns_all_when_k_exceeds_stream_length():
    data = [1, 2, 3]
    assert sorted(reservoir_sample(data, 10)) == [1, 2, 3]


def test_returns_exact_k_items():
    data = range(100)
    assert len(reservoir_sample(data, 5)) == 5


def test_items_come_from_original_stream():
    data = list(range(50))
    result = reservoir_sample(data, 10)
    assert all(item in data for item in result)


def test_works_with_generators():
    def gen():
        for i in range(20):
            yield i

    result = reservoir_sample(gen(), 3)
    assert len(result) == 3
    assert all(0 <= x < 20 for x in result)


def test_negative_k_raises():
    try:
        reservoir_sample(range(10), -1)
        assert False, "Expected ValueError"
    except ValueError:
        pass


def test_distribution_is_roughly_uniform():
    """Statistical test: over many runs each position should be sampled ~equally."""
    n, k, trials = 10, 3, 5000
    counts = [0] * n
    for _ in range(trials):
        for item in reservoir_sample(range(n), k):
            counts[item] += 1
    expected = trials * k / n
    # Each count should be within 3 standard deviations of expected
    import math
    std = math.sqrt(trials * k * (n - k) / (n * n))
    for i, c in enumerate(counts):
        assert abs(c - expected) < 4 * std, f"Position {i}: count {c} far from expected {expected}"


if __name__ == "__main__":
    import sys
    tests = [v for k, v in globals().items() if k.startswith("test_")]
    failures = 0
    for t in tests:
        try:
            t()
            print(f"  PASS  {t.__name__}")
        except Exception as e:
            failures += 1
            print(f"  FAIL  {t.__name__}: {e}")
    sys.exit(1 if failures else 0)
